INSERT INTO `seo_meta` (`id`, `page`, `meta_title`, `meta_description`, `content`, `menu_label`, `menu_icon`, `meta_keywords`, `og_title`, `og_description`, `og_image`, `canonical_url`, `no_index`, `created_at`, `updated_at`) VALUES
(1, 'home', 'Aakar Dermatology | Skin, Hair & Laser Clinic in Lalitpur, Nepal', 'Aakar Dermatology offers comprehensive medical & aesthetic dermatology services in Lalitpur, Nepal. Led by Dr. Rajan Tajhya, expert in LASER and Dermato-surgery.', NULL, NULL, NULL, 'dermatology, skin clinic, hair clinic, laser treatment, Lalitpur, Nepal, Dr. Rajan Tajhya, Aakar Dermatology', 'Aakar Dermatology | Skin, Hair & Laser Clinic', 'Comprehensive Medical & Aesthetic Dermatology Services in Lalitpur. Expert in LASER, Hair Transplant & Dermato-surgery.', NULL, 'https://aakardermatology.com/', 0, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(2, 'services', 'Our Dermatology Services | Aakar Dermatology Lalitpur', 'Explore our complete range of skin, hair & laser treatment services at Aakar Dermatology. From acne treatment to hair transplant, we have personalized solutions for you.', NULL, NULL, NULL, 'dermatology services, skin treatment, hair transplant, laser treatment, acne treatment, Lalitpur Nepal', 'Dermatology Services | Aakar Dermatology', 'Complete range of medical and aesthetic dermatology services tailored for you.', NULL, 'https://aakardermatology.com/services', 0, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(3, 'about', 'About Dr. Rajan Tajhya | Aakar Dermatology Lalitpur', 'Meet Dr. Rajan Tajhya, Founder of Aakar Dermatology. A decade of expertise in LASER and Dermato-surgery. Providing compassionate, personalized dermatology care in Lalitpur, Nepal.', NULL, NULL, NULL, 'Dr. Rajan Tajhya, dermatologist, laser specialist, dermato-surgery, Aakar Dermatology, about', 'About Dr. Rajan Tajhya | Aakar Dermatology', 'A decade of expertise in LASER and Dermato-surgery at Aakar Dermatology, Lalitpur.', NULL, 'https://aakardermatology.com/about', 0, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(4, 'blog', 'Skin & Hair Care Blog | Aakar Dermatology', 'Read expert tips, treatment guides, and skin care advice from Dr. Rajan Tajhya and the Aakar Dermatology team.', NULL, NULL, NULL, 'skin care tips, hair care, dermatology blog, laser treatment guide, Aakar Dermatology', 'Skin & Hair Care Blog | Aakar Dermatology', 'Expert skin care tips, treatment guides and dermatology advice from Aakar Dermatology.', NULL, 'https://aakardermatology.com/blog', 0, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(5, 'contact', 'Contact Us | Book Appointment at Aakar Dermatology', 'Contact Aakar Dermatology in Lalitpur, Nepal. Book your consultation with Dr. Rajan Tajhya today. Call us or fill the appointment form.', NULL, NULL, NULL, 'contact Aakar Dermatology, book appointment, dermatologist Lalitpur, skin clinic contact', 'Contact & Appointment | Aakar Dermatology', 'Book your consultation at Aakar Dermatology, Lalitpur. Expert skin, hair & laser care.', NULL, 'https://aakardermatology.com/contact', 0, '2026-09-18 20:10:23', '2026-09-18 20:10:23'),
(6, 'videos', 'Video Tutorials | Aakar Dermatology', 'Watch practical skin, hair, and treatment tutorials from Aakar Dermatology.', NULL, 'Videos', 'play', 'dermatology videos, skin care tutorials, hair care videos, Aakar Dermatology', NULL, NULL, NULL, 'https://aakardermatology.com/videos', 0, '2026-09-19 02:43:21', '2026-09-19 02:43:21'),
(7, 'privacy_policy', 'Privacy Policy | Aakar Dermatology', 'Read the Aakar Dermatology privacy policy and learn how we handle personal information.', '<h2>Privacy Policy</h2><p>Aakar Dermatology respects your privacy. We collect only the information needed to respond to enquiries, manage appointments, and provide better care.</p><h3>How we use information</h3><p>Information submitted through this website is used to contact you about your request and is not sold to third parties.</p><h3>Contact</h3><p>For privacy questions, please contact our clinic directly.</p>', 'Privacy Policy', 'shield', NULL, NULL, NULL, NULL, 'https://aakardermatology.com/privacy-policy', 0, '2026-09-19 02:43:21', '2026-09-19 02:43:21'),
(8, 'terms_and_conditions', 'Terms & Conditions | Aakar Dermatology', 'Read the terms and conditions for using the Aakar Dermatology website and online services.', '<h2>Terms &amp; Conditions</h2><p>By using this website, you agree to use the information responsibly and understand that website content does not replace a consultation with a qualified medical professional.</p><h3>Appointments</h3><p>Appointment requests are subject to confirmation by the clinic team. Treatment recommendations are made after an appropriate clinical assessment.</p><h3>Website content</h3><p>We aim to keep information accurate and current, but details may change without notice.</p>', 'Terms & Conditions', 'document', NULL, NULL, NULL, NULL, 'https://aakardermatology.com/terms-and-conditions', 0, '2026-09-19 02:43:21', '2026-09-19 02:43:21');

