INSERT INTO `services` (`id`, `title`, `slug`, `category`, `icon`, `image`, `short_description`, `full_description`, `meta_title`, `meta_description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(2, 'Hair Transplant', 'hair-transplant', 'hair', 'hair', 'services/hair-transplant.webp', 'Advanced FUE and FUT hair transplant techniques for natural-looking, permanent hair restoration results.', '<p>Hair loss can deeply affect your confidence and self-image. Dr. Rajan Tajhya is an expert in hair transplant surgery using the latest Follicular Unit Extraction (FUE) and Follicular Unit Transplantation (FUT) methods.</p><p>The procedure involves harvesting healthy hair follicles from the donor area and transplanting them to areas of thinning or baldness. Results are natural-looking, permanent, and life-changing.</p>', 'Hair Transplant in Lalitpur | Aakar Dermatology', 'Expert FUE & FUT hair transplant surgery by Dr. Rajan Tajhya at Aakar Dermatology, Lalitpur. Natural, permanent results.', 1, 1, 2, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(3, 'Eyelid Surgery (Blepharoplasty)', 'eyelid-surgery', 'surgical', 'eye', 'services/eyelid-surgery.webp', 'Precise eyelid surgery to correct droopy eyelids, under-eye bags, and restore a youthful, refreshed appearance.', '<p>Blepharoplasty, or eyelid surgery, is a delicate procedure that removes excess skin, fat, and muscle from the upper or lower eyelids. Dr. Rajan Tajhya\'s precise surgical technique ensures natural results that open up your eyes and refresh your appearance.</p><p>Whether for cosmetic improvement or to correct functional issues like impaired vision from drooping eyelids, our blepharoplasty procedures are performed with utmost care and precision.</p>', 'Eyelid Surgery Lalitpur | Blepharoplasty | Aakar Dermatology', 'Expert blepharoplasty (eyelid surgery) by Dr. Rajan Tajhya at Aakar Dermatology. Refresh your look with precise, natural eyelid correction.', 1, 1, 3, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(4, 'Laser Hair Removal', 'laser-hair-removal', 'laser', 'laser', 'services/laser-hair-removal.webp', 'Safe and effective laser hair removal for smooth, hair-free skin on face, underarms, legs, and body.', '<p>Tired of shaving, waxing, or threading? Laser hair removal at Aakar Dermatology offers a long-lasting solution for unwanted body hair. Using state-of-the-art laser technology, we target hair follicles precisely while protecting the surrounding skin.</p><p>Suitable for all skin types, our laser hair removal sessions are quick, virtually painless, and deliver permanent hair reduction with each session.</p>', 'Laser Hair Removal Lalitpur | Aakar Dermatology', 'Permanent laser hair removal at Aakar Dermatology, Lalitpur. Safe, effective & suitable for all skin types. Book today.', 1, 1, 4, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(5, 'Plasma-Rich Platelet (PRP) Therapy', 'prp-therapy', 'hair', 'prp', 'services/prp-therapy.webp', 'Natural hair regrowth and skin rejuvenation using your own platelet-rich plasma for remarkable results.', '<p>PRP (Platelet-Rich Plasma) therapy harnesses your body\'s natural healing powers to stimulate hair regrowth and rejuvenate the skin. A small amount of your blood is processed to concentrate the growth factors, which are then injected into the treatment area.</p><p>PRP is highly effective for treating androgenetic alopecia (pattern baldness), thinning hair, and can also be used for facial rejuvenation, reducing fine lines and improving skin texture.</p>', 'PRP Therapy Lalitpur | Hair & Skin Rejuvenation | Aakar Dermatology', 'PRP therapy for hair regrowth and skin rejuvenation at Aakar Dermatology. Natural, safe treatment using your own growth factors.', 0, 1, 5, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(6, 'Laser Facial Treatment', 'laser-facial', 'laser', 'laser-face', 'services/laser-facial.webp', 'Rejuvenate your skin with targeted laser facial treatments that reduce pigmentation, fine lines, and improve overall tone.', '<p>Laser facial treatments at Aakar Dermatology address a wide range of skin concerns including hyperpigmentation, sun damage, acne scars, fine lines, and uneven skin tone. Our advanced laser systems deliver precise energy to targeted areas, stimulating collagen production and skin renewal.</p><p>The result is brighter, smoother, and more youthful-looking skin with minimal downtime.</p>', 'Laser Facial Treatment Lalitpur | Skin Rejuvenation | Aakar Dermatology', 'Advanced laser facial treatments for pigmentation, acne scars & skin rejuvenation at Aakar Dermatology. Safe, effective & tailored for you.', 1, 1, 6, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(7, 'Tattoo Removal', 'tattoo-removal', 'laser', 'tattoo', 'services/tattoo-removal.webp', 'Safe and effective laser tattoo removal that breaks down ink particles for gradual, complete tattoo clearance.', '<p>Changed your mind about a tattoo? Our advanced Q-switched laser technology effectively breaks down tattoo ink particles of all colors, allowing your body to naturally eliminate them. Multiple sessions are usually required depending on the tattoo\'s size, color, and age.</p><p>The procedure is safe, minimally invasive, and performed by our expert team to minimize scarring and ensure the best possible results.</p>', 'Laser Tattoo Removal Lalitpur | Aakar Dermatology', 'Safe laser tattoo removal at Aakar Dermatology, Lalitpur. Effective removal for all colors & skin types. Book your consultation today.', 0, 1, 7, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(8, 'Skin Treatment', 'skin-treatment', 'skin', 'skin', 'services/skin-treatment.webp', 'Comprehensive medical skin treatments for eczema, psoriasis, pigmentation, and other dermatological conditions.', '<p>At Aakar Dermatology, we diagnose and treat the full spectrum of skin conditions. From common concerns like eczema, psoriasis, and vitiligo to complex dermatological disorders—our evidence-based approach ensures accurate diagnosis and effective treatment.</p><p>We combine medical management with aesthetic solutions to not only treat your condition but also restore your skin\'s natural beauty and your confidence.</p>', 'Medical Skin Treatment Lalitpur | Aakar Dermatology', 'Expert medical skin treatment for eczema, psoriasis, pigmentation & more at Aakar Dermatology. Personalized, evidence-based dermatology care.', 0, 1, 8, '2026-09-18 20:10:23', '2026-09-19 00:38:36'),
(9, 'Acne Treatment', 'acne-treatment', 'skin', 'acne', NULL, 'Comprehensive acne management using advanced medical therapies tailored to your skin type and severity.', '<p>Acne is one of the most common skin conditions affecting people of all ages. At Aakar Dermatology, we provide personalized acne treatment plans that address the root cause of your breakouts—whether hormonal, bacterial, or lifestyle-related.</p><p>Our treatments include topical therapies, oral medications, chemical peels, laser therapy, and comedone extraction. We also offer scar revision treatments to restore smooth, even skin after acne resolves.</p>', 'Acne Treatment in Lalitpur | Aakar Dermatology', 'Expert acne treatment at Aakar Dermatology. Personalized plans including medications, peels, laser & scar revision. Book your consultation today.', 1, 1, 1, '2026-09-19 01:54:44', '2026-09-19 01:54:44');

