INSERT INTO `team_members` (`id`, `name`, `designation`, `qualification`, `specialization`, `photo`, `bio`, `years_experience`, `total_patients`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Dr. Rajan Tajhya', 'Founder & Lead Dermatologist', 'MD, Dermatology & Venereology', 'LASER & Dermato-surgery', NULL, 'Dr. Rajan Tajhya\'s journey in dermatology spans over a decade in hospital settings, where he developed deep expertise as a specialist in LASER and Dermato-surgery. Now, with the founding of Aakar Dermatology, he has reached a new milestone—creating a practice where advanced surgical and laser expertise meets compassionate, personalized care. Every procedure, from complex hair transplants to precise eyelid surgeries, reflects his commitment to helping you achieve results that transform not just your appearance, but your confidence.', 10, 86, 1, 1, 1, '2026-09-18 20:10:23', '2026-09-18 20:10:23');

