INSERT INTO `videos` (`id`, `title`, `slug`, `category`, `description`, `video_url`, `thumbnail_url`, `duration`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Your Skin Consultation: What to Expect', 'your-skin-consultation-what-to-expect', 'Getting Started', 'A simple guide to preparing for your first dermatology consultation.', 'https://www.youtube.com/shorts/3STJH_sET_Q', 'https://img.youtube.com/vi/3STJH_sET_Q/hqdefault.jpg', '04:12', 1, 1, 1, '2026-09-19 02:09:21', '2026-09-19 04:30:54'),
(2, 'Daily Skin Care Routine for Healthy Skin', 'daily-skin-care-routine-for-healthy-skin', 'Skin Care', 'Build a practical routine for cleansing, hydration, and sun protection.', 'https://www.youtube.com/shorts/ZWwmQ9GM-CA', 'https://img.youtube.com/vi/ZWwmQ9GM-CA/hqdefault.jpg', '06:48', 1, 1, 2, '2026-09-19 02:09:21', '2026-09-19 04:31:29'),
(3, 'Understanding Acne and Its Treatments', 'understanding-acne-and-its-treatments', 'Acne', 'Learn what causes acne and when professional treatment can help.', 'https://www.youtube.com/results?search_query=Aakar+Dermatology+Understanding+Acne+and+Its+Treatments', NULL, '07:20', 0, 1, 3, '2026-09-19 02:09:21', '2026-09-19 02:09:21'),
(4, 'Laser Hair Removal Explained', 'laser-hair-removal-explained', 'Laser Treatments', 'How laser hair reduction works and how to prepare for a session.', 'https://www.youtube.com/results?search_query=Aakar+Dermatology+Laser+Hair+Removal+Explained', NULL, '05:36', 0, 1, 4, '2026-09-19 02:09:21', '2026-09-19 02:09:21'),
(5, 'What to Know Before a Hair Transplant', 'what-to-know-before-a-hair-transplant', 'Hair Care', 'A clear overview of candidacy, preparation, and recovery.', 'https://www.youtube.com/results?search_query=Aakar+Dermatology+What+to+Know+Before+a+Hair+Transplant', NULL, '08:05', 0, 1, 5, '2026-09-19 02:09:21', '2026-09-19 02:09:21'),
(6, 'Pigmentation: Causes and Care Options', 'pigmentation-causes-and-care-options', 'Skin Concerns', 'Understand common pigmentation concerns and evidence-based care.', 'https://www.youtube.com/results?search_query=Aakar+Dermatology+Pigmentation%3A+Causes+and+Care+Options', NULL, '05:18', 0, 1, 6, '2026-09-19 02:09:21', '2026-09-19 02:09:21'),
(7, 'Sun Protection That Actually Works', 'sun-protection-that-actually-works', 'Everyday Care', 'Simple sunscreen habits that protect your skin every day.', 'https://www.youtube.com/results?search_query=Aakar+Dermatology+Sun+Protection+That+Actually+Works', NULL, '03:42', 0, 1, 7, '2026-09-19 02:09:21', '2026-09-19 02:09:21'),
(8, 'Aftercare Following a Skin Treatment', 'aftercare-following-a-skin-treatment', 'Treatment Aftercare', 'Helpful aftercare guidance to support a smooth recovery.', 'https://www.youtube.com/results?search_query=Aakar+Dermatology+Aftercare+Following+a+Skin+Treatment', NULL, '04:55', 0, 1, 8, '2026-09-19 02:09:21', '2026-09-19 02:09:21');

